import axios from 'axios';
import React, { useState, useEffect, useRef } from 'react';
import { useParams, useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';
import api, { PEXELS_KEY } from '../api';

const SUGGESTIONS = ['Nature','Technology','Travel','Architecture','People','Food','Space','Art','Business','Fashion'];

function handleDownload(url, e) {
  e.stopPropagation();
  e.preventDefault();
  fetch(url)
    .then(function(res) { return res.blob(); })
    .then(function(blob) {
      var blobUrl = window.URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = blobUrl;
      a.download = 'inkwell-image.jpg';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(blobUrl);
    })
    .catch(function() { window.open(url, '_blank'); });
}

function PinCard(props) {
  var img = props.img;
  var onSelect = props.onSelect;
  var imgRef = useRef(null);
  var ratio = img.height / img.width;
  var pt = (ratio * 100).toFixed(2) + '%';

  useEffect(function() {
    if (imgRef.current && imgRef.current.complete) {
      imgRef.current.style.opacity = '1';
      imgRef.current.style.transform = 'translateY(0)';
    }
  }, []);

  return React.createElement(
    'div',
    {
      style: {
        position: 'relative',
        borderRadius: 16,
        overflow: 'hidden',
        cursor: 'pointer',
        background: '#f0f0f0',
        breakInside: 'avoid',
        marginBottom: 12,
        display: 'block',
        width: '100%',
        boxSizing: 'border-box',
      },
      className: 'pin-card',
      onClick: function() { onSelect(img); },
    },
    React.createElement(
      'div',
      { style: { position: 'relative', width: '100%', paddingTop: pt } },
      React.createElement('img', {
        ref: imgRef,
        src: img.src.medium,
        alt: img.alt,
        className: 'pin-img',
        style: {
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          display: 'block',
          borderRadius: 16,
          opacity: 0,
          transform: 'translateY(12px)',
          transition: 'opacity 0.5s ease, transform 0.5s ease',
        },
        onLoad: function() {
